insert into public.topics (slug, draft, published, published_version, published_at)
values ('whiskey', $cfg${"slug":"whiskey","name":"WhiskeyList","tagline":"Nose it. Taste it. Score it.","itemNoun":"pour","favicon":"🥃","beta":true,"correctionLink":true,"theme":{"fontsHref":"https://fonts.googleapis.com/css2?family=DM+Serif+Display&family=Source+Sans+3:wght@400;500;600&family=IBM+Plex+Mono:wght@500;600&display=swap","fonts":{"display":"\"DM Serif Display\", Georgia, serif","body":"\"Source Sans 3\", \"Segoe UI\", system-ui, sans-serif","mono":"\"IBM Plex Mono\", ui-monospace, Consolas, monospace"},"light":{"bg":"#EFE9E1","bgInk":"#24180F","bgMuted":"#6B5B4D","card":"#FFFFFF","ink":"#24180F","muted":"#6B5B4D","line":"#DDD3C6","field":"#FFFFFF","headerAccent":"#E2A653","header":"#3A2416","headerInk":"#F6EFE6","headerMuted":"#CBB8A3","headerLine":"#5E4330","accent":"#B8741F","accentInk":"#FFFFFF","accentSoft":"#F5E6D0","title":"#3A2416","link":"#8A4E12","danger":"#8E2B22","dangerSoft":"#F5DFDB","good":"#2F7A3D"},"dark":{"bg":"#17110C","bgInk":"#EFE6DA","bgMuted":"#A8988A","card":"#221913","ink":"#EFE6DA","muted":"#A8988A","line":"#3D2E22","field":"#17110C","accentSoft":"#3A2A17","title":"#F0D2A8","link":"#E2A653","dangerSoft":"#3A1C18"},"logo":"<svg viewBox=\"0 0 32 32\" aria-hidden=\"true\"><path d=\"M10 3h12c.6 4.5-.2 7.7-1.9 10.3-1.3 2-1.9 3.6-1.6 6.2l.3 3.5h3.2v3H10v-3h3.2l.3-3.5c.3-2.6-.3-4.2-1.6-6.2C10.2 10.7 9.4 7.5 10 3z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linejoin=\"round\"/><path d=\"M10.6 9.5h10.8c-.3 1.4-.8 2.6-1.5 3.6-.6 1-1.1 1.9-1.4 2.9h-5c-.3-1-.8-1.9-1.4-2.9-.7-1-1.2-2.2-1.5-3.6z\" fill=\"#E2A653\"/></svg>","totalStyle":"bar"},"form":[{"type":"photo","bind":"photo","label":"Photo","layout":"beside-next"},{"type":"text","bind":"item_name","label":"Whiskey","placeholder":"Name on the label","required":true,"group":"photo"},{"type":"text","bind":"maker","label":"Distillery or brand","placeholder":"Who made or bottled it","group":"photo"},{"type":"whiskeyPicker","label":"What are you drinking?","bind":"style","familyBind":"answers.family","styleBind":"answers.style_id","regionBind":"answers.region","countryBind":"answers.country"},{"type":"number","bind":"answers.proof","label":"Proof","placeholder":"e.g. 100","min":40,"max":200,"step":0.1,"half":true,"showAbv":true},{"type":"age","bind":"answers.age","label":"Age","half":true},{"type":"multipills","bind":"answers.label_tags","label":"On the label","options":["Wheated","High-rye","Cask strength","Single barrel","Small batch","Bottled-in-bond","Non-chill-filtered","Finished"],"detail":{"option":"Finished","bind":"answers.finish_cask","placeholder":"Finished in what cask? e.g. sherry, port, wine"},"tips":{"Bottled-in-bond":"US rule: one distilling season, one distiller at one distillery, at least 4 years in a bonded warehouse, bottled at exactly 100 proof.","Cask strength":"Bottled at barrel proof, without being watered down.","Finished":"Spent extra time in a second cask, often one that held wine, sherry or port."}},{"type":"pills","bind":"answers.serving","label":"Served","options":["Neat","Few drops of water","Splash","On ice"],"toggle":true,"hint":"For judging, neat or with a few drops of water works best. Water can open up aromas, especially in high-proof whiskey. Ice numbs flavor."},{"type":"location","label":"Where you drank it","placeholder":"Bar, distillery, home"},{"type":"sheet","bind":"answers.sections","flawsBind":"answers.flaws","sections":[{"key":"appearance","label":"Appearance","max":10,"tip":{"what":"Color, clarity and how the whiskey moves in the glass. Only 10 points; it sets expectations more than it decides scores.","how":"Tilt the glass against a white background. Look at color, clarity, then swirl and watch the legs."},"rows":[{"key":"color","label":"Color","wide":true,"scale":["Pale straw","Straw","Gold","Amber","Copper","Mahogany","Deep brown"],"swatch":["#F3E7A6","#EBCF6A","#DDAA3A","#C47F22","#A85A1E","#7A3519","#4A2212"],"tip":{"what":"Color comes from the barrel. Longer aging, new charred oak and wine or sherry casks all darken whiskey.","how":"In styles that allow caramel coloring, color is a weak guide to age. Bourbon and straight whiskeys can't add any, so their color is all barrel."}},{"key":"clarity","label":"Clarity","scale":["Brilliant","Clear","Hazy"],"tip":{"what":"Most whiskey is clear. Haze can appear in non-chill-filtered whiskey, especially after adding water or ice.","how":"That haze is natural oils and fatty acids, not a flaw. Bottles labeled non-chill-filtered often show it."}},{"key":"legs","label":"Legs","scale":["Thin","Medium","Thick"],"tip":{"what":"The streaks that run down the glass after a swirl.","how":"Legs reflect alcohol strength and texture, not quality. High-proof whiskeys show slow, thick legs."}}]},{"key":"nose","label":"Nose","max":25,"tip":{"what":"What you smell. A quarter of the score, because most of what we call taste happens in the nose.","how":"Keep your mouth slightly open and sniff gently at the rim. Don't bury your nose: alcohol numbs it fast. Move around the glass, take a break, come back. A few drops of water often open it up."},"rows":[{"key":"sweet","label":"Sweet","scale":["None","L","M","H"],"tags":"sweet","tip":{"what":"Sweet aromas: caramel, vanilla, toffee, honey. Much of it comes from the barrel's toasted and charred wood.","how":"Think dessert aisle. Bourbon in new charred oak is usually sweet; many Scotches are less so."}},{"key":"fruit","label":"Fruit","scale":["None","L","M","H"],"tags":"fruit","tip":{"what":"Fruit aromas: fresh fruit (apple, pear, citrus) from fermentation, or dried fruit (raisin, fig) often from sherry casks.","how":"Fresh and bright points to the spirit itself; jammy and dried often points to the cask."}},{"key":"spice","label":"Spice","scale":["None","L","M","H"],"tags":"spice","tip":{"what":"Spice aromas: pepper, cinnamon, clove, mint. Rye grain and oak are the usual sources.","how":"Rye whiskeys lead with spice. A peppery tingle is spice; a burn is alcohol heat."}},{"key":"oak","label":"Oak","scale":["None","L","M","H"],"tags":"oak","tip":{"what":"Wood aromas: toasted oak, char, leather, tobacco, coconut. Stronger with age and with new barrels.","how":"Pleasant oak tastes like a cigar box or a lumber yard. Too much turns bitter and drying."}},{"key":"grain","label":"Grain","scale":["None","L","M","H"],"tags":"grain","tip":{"what":"Grain aromas: corn, bread, cereal, malt. Strongest in young whiskeys and those with less barrel influence.","how":"Breakfast cereal and bread crust. Corn whiskey and young craft whiskeys show it most."}},{"key":"smoke","label":"Smoke","scale":["None","L","M","H"],"tags":"smoke","spotlight":["scotch"],"spotlightNote":"Peat smoke is common in Scotch, especially from Islay.","tip":{"what":"Smoke aromas: usually peat, from malted barley dried over peat fires. Can read as campfire, ash, iodine, seaweed or medicinal.","how":"Many Scotches, especially from Islay, are peated. Most bourbon has none: char from the barrel is different and reads as toasty rather than smoky."}},{"key":"heat","label":"Alcohol heat","scale":["None","L","M","H"],"tip":{"what":"The prickle of ethanol in the nose.","how":"Some heat is expected, more so at high proof. A sharp sting that hides everything else counts against the whiskey."}}]},{"key":"palate","label":"Palate","max":30,"tip":{"what":"What you taste, the biggest section. Includes flavor, weight and how it develops in your mouth.","how":"Take a small first sip to adjust to the alcohol, then a real sip held for a few seconds. Notice the start, the middle and how it changes."},"rows":[{"key":"sweet","label":"Sweet","scale":["None","L","M","H"],"tags":"sweet","tip":{"what":"Sweet flavors: caramel, vanilla, toffee, honey. Much of it comes from the barrel's toasted and charred wood.","how":"Think dessert aisle. Bourbon in new charred oak is usually sweet; many Scotches are less so."}},{"key":"fruit","label":"Fruit","scale":["None","L","M","H"],"tags":"fruit","tip":{"what":"Fruit flavors: fresh fruit (apple, pear, citrus) from fermentation, or dried fruit (raisin, fig) often from sherry casks.","how":"Fresh and bright points to the spirit itself; jammy and dried often points to the cask."}},{"key":"spice","label":"Spice","scale":["None","L","M","H"],"tags":"spice","tip":{"what":"Spice flavors: pepper, cinnamon, clove, mint. Rye grain and oak are the usual sources.","how":"Rye whiskeys lead with spice. A peppery tingle is spice; a burn is alcohol heat."}},{"key":"oak","label":"Oak","scale":["None","L","M","H"],"tags":"oak","tip":{"what":"Wood flavors: toasted oak, char, leather, tobacco, coconut. Stronger with age and with new barrels.","how":"Pleasant oak tastes like a cigar box or a lumber yard. Too much turns bitter and drying."}},{"key":"grain","label":"Grain","scale":["None","L","M","H"],"tags":"grain","tip":{"what":"Grain flavors: corn, bread, cereal, malt. Strongest in young whiskeys and those with less barrel influence.","how":"Breakfast cereal and bread crust. Corn whiskey and young craft whiskeys show it most."}},{"key":"smoke","label":"Smoke","scale":["None","L","M","H"],"tags":"smoke","spotlight":["scotch"],"spotlightNote":"Peat smoke is common in Scotch, especially from Islay.","tip":{"what":"Smoke flavors: usually peat, from malted barley dried over peat fires. Can read as campfire, ash, iodine, seaweed or medicinal.","how":"Many Scotches, especially from Islay, are peated. Most bourbon has none: char from the barrel is different and reads as toasty rather than smoky."}},{"key":"body","label":"Body","scale":["Thin","Medium","Oily"],"tip":{"what":"The whiskey's weight and texture.","how":"Thin feels watery. Oily coats your tongue. Pot still and non-chill-filtered whiskeys often feel richer."}}]},{"key":"finish","label":"Finish","max":20,"tip":{"what":"What stays after you swallow. A long, pleasant finish is one of the marks of a great whiskey.","how":"After swallowing, breathe out slowly through your nose and count how long the flavor lasts."},"rows":[{"key":"length","label":"Length","scale":["Short","Medium","Long"],"tip":{"what":"How long the flavor lasts after swallowing.","how":"Short fades in a few seconds. Long lingers for a minute or more."}},{"key":"heat","label":"Heat","scale":["None","L","M","H"],"tip":{"what":"Warmth from alcohol as it goes down.","how":"A gentle warmth down the chest is the classic 'Kentucky hug.' A harsh burn is a fault."}},{"key":"character","label":"Character","scale":["Dry","","Even","","Sweet"],"ends":true,"tags":"finish","tip":{"what":"How the finish leans: dry and drying, or sweet and lingering.","how":"Tag what stays with you: oak, spice, smoke, sweetness."}}]},{"key":"overall","label":"Overall","max":15,"tip":{"what":"Your overall judgment: how well it all fits together and how much you'd want another pour.","how":"Step back from the parts. Would you buy this bottle? Recommend it?"},"rows":[{"key":"balance","label":"Balance","scale":["Integrated","","","","Disjointed"],"ends":true,"tip":{"what":"Whether sweetness, spice, oak, fruit and alcohol work together.","how":"Disjointed whiskey has one element sticking out, like raw alcohol or heavy oak."}},{"key":"complexity","label":"Complexity","scale":["Layered","","","","Simple"],"ends":true,"tip":{"what":"How many distinct things you can find, and whether they change as you sip.","how":"Simple isn't bad, especially at a low price. Layered whiskeys reveal more with time and water."}},{"key":"intangibles","label":"Intangibles","scale":["Memorable","","","","Forgettable"],"ends":true,"tip":{"what":"Drinkability, character, the part a checklist misses.","how":"Would you remember this pour next week?"}}]}],"flaws":[{"key":"hot","label":"Too hot","tip":"Burning, sharp alcohol that hides the flavor.","cause":"Very young whiskey, or high proof without enough flavor to carry it."},{"key":"solvent","label":"Solvent","tip":"Nail polish remover, paint thinner.","cause":"Heavy fusel alcohols from a rushed or poorly cut distillation."},{"key":"overoaked","label":"Over-oaked","tip":"Bitter, tannic, drying wood, like chewing a pencil.","cause":"Too long in an active barrel, or small barrels used to force age quickly."},{"key":"young","label":"Young / grainy","tip":"Raw grain, wet cardboard, new-make spirit character.","cause":"Not enough time in the barrel to round off the spirit."},{"key":"sulfur","label":"Sulfur","tip":"Struck match, rubber, cooked cabbage.","cause":"From distillation, or from sulfur candles used to clean wine casks before filling."},{"key":"musty","label":"Musty / cork","tip":"Damp cardboard, wet basement, moldy.","cause":"Cork taint (TCA) from a bad cork, or a musty cask."},{"key":"metallic","label":"Metallic","tip":"Tinny, coin-like.","cause":"Equipment or water contamination."},{"key":"soapy","label":"Soapy","tip":"Soap or detergent.","cause":"Fatty acids, or a glass with soap residue. Rinse the glass and try again first."},{"key":"sour","label":"Sour","tip":"Vinegar or sour milk.","cause":"Bacterial problems during fermentation."}],"flawLevels":["L","M","H"],"descriptors":{"sweet":["Caramel","Vanilla","Toffee","Brown sugar","Honey","Maple","Butterscotch","Molasses","Chocolate","Marzipan"],"fruit":["Cherry","Orange peel","Lemon","Apple","Pear","Banana","Raisin","Dried fig","Stone fruit","Tropical","Berry","Sherry"],"spice":["Cinnamon","Clove","Nutmeg","Black pepper","Rye spice","Ginger","Mint","Anise","Baking spice"],"oak":["Toasted oak","Char","Cedar","Sawdust","Leather","Tobacco","Coconut","Dill","Tannic"],"grain":["Corn","Bread","Cereal","Biscuit","Malt","Nutty","Porridge"],"smoke":["Campfire","Peat","Ash","Iodine","Medicinal","Seaweed","Brine","Bacon"],"finish":["Warm","Dry","Sweet","Spicy","Oaky","Smoky","Bitter","Clean","Lingering"]},"requireAll":true},{"type":"textarea","bind":"comments","label":"Comments","placeholder":"What stood out? Would you buy the bottle?"}],"bands":[{"min":90,"label":"Exceptional","color":"#2F7A3D","note":"A standout pour"},{"min":80,"label":"Excellent","color":"#4E8A3A","note":"Excellent, with minor quibbles"},{"min":70,"label":"Very good","color":"#C8862B","note":"Very good, worth buying"},{"min":60,"label":"Good","color":"#B26A1F","note":"Good, but unremarkable"},{"min":50,"label":"Fair","color":"#8E3B1F","note":"Noticeable problems"},{"min":0,"label":"Problematic","color":"#7A2020","note":"Major flaws"}],"list":{"defaultSort":"recent","lines":[["maker","styleFull"],["place","date"]],"badges":[{"bind":"answers.proof","tone":"plain","suffix":" proof"},{"bind":"answers.age_label","tone":"plain"}],"commentsIn":"detail","photoInDetail":true,"detailExtras":[{"bind":"answers.label_tags","label":"On the label"},{"bind":"answers.finish_cask","label":"Finished in"},{"bind":"answers.serving","label":"Served"}]},"about":[{"heading":null,"text":"A shared scoresheet for judging whiskey: American, Scotch, Irish, Japanese, Canadian and beyond. WhiskeyList is in beta, so tell us what's missing or wrong."},{"heading":"Where the style rules come from","text":"Style cards summarize each category's public rules: the US Standards of Identity (27 CFR 5.143), Tennessee Code 57-2-106, the Scotch Whisky Regulations 2009, the Irish Whiskey Technical File, Canada's Food and Drug Regulations, and the Japan Spirits & Liqueurs Makers Association's labeling standards. Each card links to its source. Flavor notes describe common tendencies, not rules."},{"heading":null,"text":"WhiskeyList isn't affiliated with any distillery or trade body. Please enjoy responsibly."}]}$cfg$::jsonb, $cfg${"slug":"whiskey","name":"WhiskeyList","tagline":"Nose it. Taste it. Score it.","itemNoun":"pour","favicon":"🥃","beta":true,"correctionLink":true,"theme":{"fontsHref":"https://fonts.googleapis.com/css2?family=DM+Serif+Display&family=Source+Sans+3:wght@400;500;600&family=IBM+Plex+Mono:wght@500;600&display=swap","fonts":{"display":"\"DM Serif Display\", Georgia, serif","body":"\"Source Sans 3\", \"Segoe UI\", system-ui, sans-serif","mono":"\"IBM 